const searchInput = document.getElementById('searchInput');
const resultsContainer = document.getElementById('resultsContainer');

searchInput.addEventListener('input', function(e) {
    const query = e.target.value.toLowerCase().trim();
    
    if (query.length < 2) {
        resultsContainer.innerHTML = '<p class="no-results">Start typing to search for your certificate...</p>';
        return;
    }

    const filtered = participants.filter(person => 
        person.name.toLowerCase().includes(query)
    );

    displayResults(filtered);
});

function displayResults(results) {
    if (results.length === 0) {
        resultsContainer.innerHTML = '<p class="no-results">No certificates found matching that name.</p>';
        return;
    }

    const html = results.map(person => `
        <div class="cert-item">
            <div class="cert-info">
                <h4>${person.name}</h4>
                <span>${person.category}</span>
            </div>
            <a href="${person.file}" download="${person.fileName}" class="download-btn">
                <i class="fas fa-download"></i> Download
            </a>
        </div>
    `).join('');

    resultsContainer.innerHTML = html;
}

